import subprocess, re, random
random.seed(1)

def oracle(r,a):
    inp=f"@@\n-{r}\n+{a}\n".encode()
    p=subprocess.run(["./executable"],input=inp,stdout=subprocess.PIPE)
    lines=p.stdout.split(b'\n')
    def parse(line,content):
        segs=[]; parts=line.decode().split('\x1b[0m')
        for part in parts[1:]:
            m=re.match(r'((?:\x1b\[[0-9;]*m)*)(.*)',part,re.S)
            codes,txt=m.group(1),m.group(2); kind='U' if ('\x1b[41m' in codes or '\x1b[42m' in codes) else 'C'; segs.append((kind,txt))
        mapped=[]; pos=0
        for k,t in segs[1:]: mapped.append((k,t,pos,pos+len(t))); pos+=len(t)
        cls=[]
        for i,ch in enumerate(content):
            kind='?'
            for k,t,s,e in mapped:
                if s<=i<e: kind=k;break
            cls.append(kind)
        nl='?'
        for k,t,s,e in mapped:
            if t=='' and s==len(content): nl=k
        if nl=='?': nl=mapped[-1][0]
        return "".join(cls),nl
    return parse(lines[1],r),parse(lines[2],a)

def dp(R,A,mode):
 R=list(R)+['\n']; A=list(A)+['\n']; n,m=len(R),len(A)
 L=[[0]*(m+1) for _ in range(n+1)]
 for i in range(1,n+1):
  for j in range(1,m+1): L[i][j]=L[i-1][j-1]+1 if R[i-1]==A[j-1] else max(L[i-1][j],L[i][j-1])
 Rc=['U']*n; Ac=['U']*m; i,j=n,m
 while i>0 and j>0:
  if R[i-1]==A[j-1]: Rc[i-1]=Ac[j-1]='C'; i-=1;j-=1
  elif (L[i-1][j]>=L[i][j-1] if mode=='ge' else L[i-1][j]>L[i][j-1]): i-=1
  else: j-=1
 return "".join(Rc[:-1]),Rc[-1],"".join(Ac[:-1]),Ac[-1]

alpha="!@#$"
for mode in ['ge','gt']:
 matches=total=0; examples=[]
 for trial in range(200):
   n=random.randint(1,8); m=random.randint(1,8)
   r="".join(random.choice(alpha) for _ in range(n)); a="".join(random.choice(alpha) for _ in range(m))
   orc=oracle(r,a); pred=dp(r,a,mode)
   ok=(orc[0][0]==pred[0] and orc[0][1]==pred[1] and orc[1][0]==pred[2] and orc[1][1]==pred[3])
   total+=1; matches+=ok
   if not ok and len(examples)<10: examples.append((r,a,orc,pred))
 print(mode,matches,total)
 for e in examples: print(e)
