    Named(u8), // 0 black 1 red 2 green 3 yellow 4 blue 5 magenta 6 cyan 7 white
    Ansi256(u8),
    Rgb(u8, u8, u8),
}

#[derive(Clone, Copy, Debug)]
struct Face {
    fg: Option<Color>,
    bg: Option<Color>,
    bold: bool,
    dimmed: bool,
    italic: bool,
    underline: bool,
    intense: bool,
}

impl Face {
    fn empty() -> Face {
        Face {
            fg: None,
            bg: None,
            bold: false,
            dimmed: false,
            italic: false,
            underline: false,
            intense: false,
        }
    }
    fn clear(&mut self) {
        *self = Face::empty();
