// --------------------------------------------------------------- tokens

#[derive(Clone, Copy, PartialEq)]
enum TokenKind {
    Word,
    Whitespace,
    Other,
    Newline,
}

#[derive(Clone)]
struct Token {
    text: Vec<u8>,        // identity used for comparison
    display: Vec<u8>,     // bytes shown on the line
    kind: TokenKind,
    line_index: usize,    // index into Hunk.lines
    is_newline: bool,
}

fn is_mark(c: char) -> bool {
    let cp = c as u32;
    if cp < 0x300 {
        return false;
    }
    let ranges = marks::MARK_RANGES;
    let mut lo = 0usize;
    let mut hi = ranges.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let (a, b) = ranges[mid];
        if cp < a {
            hi = mid;
        } else if cp > b {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    false
}

fn is_word_char(c: char) -> bool {
    c == '_' || c.is_alphanumeric() || is_mark(c) || c == '\u{200c}' || c == '\u{200d}'
}

// Decode one character starting at `i`.  Returns (char, byte_len); the char
// is None for an invalid byte.
fn decode_char(bytes: &[u8], i: usize) -> (Option<char>, usize) {
    let b = bytes[i];
    if b < 0x80 {
        return (Some(b as char), 1);
    }
    let (need, min_cp, mut cp): (usize, u32, u32) = match b {
        0xC2..=0xDF => (1, 0x80, (b as u32) & 0x1F),
        0xE0..=0xEF => (2, 0x800, (b as u32) & 0x0F),
        0xF0..=0xF4 => (3, 0x10000, (b as u32) & 0x07),
        _ => return (None, 1),
    };
    if i + need >= bytes.len() + 1 {
        // need continuation bytes at i+1 ..= i+need
    }
    if i + need > bytes.len() {
        return (None, 1);
    }
    for k in 1..=need {
        let cb = bytes[i + k];
        if !(0x80..=0xBF).contains(&cb) {
            return (None, 1);
        }
        cp = (cp << 6) | ((cb as u32) & 0x3F);
    }
    if cp < min_cp || cp > 0x10FFFF || (0xD800..=0xDFFF).contains(&cp) {
        return (None, 1);
    }
    // Additional overlong / range checks for the 3- and 4-byte forms.
    if need == 2 {
        if b == 0xE0 && bytes[i + 1] < 0xA0 {
            return (None, 1);
        }
        if b == 0xED && bytes[i + 1] > 0x9F {
            return (None, 1);
        }
    }
    if need == 3 {
        if b == 0xF0 && bytes[i + 1] < 0x90 {
            return (None, 1);
        }
        if b == 0xF4 && bytes[i + 1] > 0x8F {
            return (None, 1);
        }
    }
    match char::from_u32(cp) {
        Some(c) => (Some(c), need + 1),
        None => (None, 1),
    }
}

fn tokenize_body(body: &[u8], line_index: usize) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut i = 0usize;
    while i < body.len() {
        let (c, len) = decode_char(body, i);
        match c {
            Some(ch) if is_word_char(ch) => {
                let start = i;
                while i < body.len() {
                    let (c2, l2) = decode_char(body, i);
                    match c2 {
                        Some(ch2) if is_word_char(ch2) => i += l2,
                        _ => break,
                    }
                }
                tokens.push(Token {
                    text: body[start..i].to_vec(),
                    display: body[start..i].to_vec(),
                    kind: TokenKind::Word,
                    line_index,
                    is_newline: false,
                });
            }
            Some(ch) if ch.is_whitespace() => {
                let start = i;
                while i < body.len() {
                    let (c2, l2) = decode_char(body, i);
                    match c2 {
                        Some(ch2) if ch2.is_whitespace() => i += l2,
                        _ => break,
                    }
                }
                tokens.push(Token {
                    text: body[start..i].to_vec(),
                    display: body[start..i].to_vec(),
                    kind: TokenKind::Whitespace,
                    line_index,
                    is_newline: false,
                });
            }
            _ => {
                tokens.push(Token {
                    text: body[i..i + len].to_vec(),
                    display: body[i..i + len].to_vec(),
                    kind: TokenKind::Other,
                    line_index,
                    is_newline: false,
                });
                i += len;
            }
        }
    }
    tokens
}

fn is_ascii_ws_byte(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | 0x0C | b'\r')
}

// --------------------------------------------------------------- LCS

fn classify_tokens(removed: &[Token], added: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let n = removed.len();
    let m = added.len();
    let mut r_common = vec![false; n];
    let mut a_common = vec![false; m];
    if n == 0 || m == 0 {
        return (r_common, a_common);
    }
    // Common prefix.
    let mut p = 0usize;
    while p < n && p < m && removed[p].text == added[p].text {
        r_common[p] = true;
        a_common[p] = true;
        p += 1;
    }
    // Common suffix (not overlapping the prefix).
    let mut s = 0usize;
    while s < n - p && s < m - p && removed[n - 1 - s].text == added[m - 1 - s].text {
        r_common[n - 1 - s] = true;
        a_common[m - 1 - s] = true;
        s += 1;
    }
    let rn = n - p - s;
    let am = m - p - s;
    if rn == 0 || am == 0 {
        return (r_common, a_common);
    }
    let r_mid = &removed[p..p + rn];
    let a_mid = &added[p..p + am];
    // DP table of LCS lengths over prefixes.
    let width = am + 1;
    let mut table = vec![0u32; (rn + 1) * width];
    for i in 1..=rn {
        for j in 1..=am {
            table[i * width + j] = if r_mid[i - 1].text == a_mid[j - 1].text {
                table[(i - 1) * width + (j - 1)] + 1
            } else {
                std::cmp::max(table[(i - 1) * width + j], table[i * width + (j - 1)])
            };
        }
    }
    let mut i = rn;
    let mut j = am;
    while i > 0 && j > 0 {
        if r_mid[i - 1].text == a_mid[j - 1].text {
            r_common[p + i - 1] = true;
            a_common[p + j - 1] = true;
            i -= 1;
            j -= 1;
        } else if table[(i - 1) * width + j] >= table[i * width + (j - 1)] {
            i -= 1;
        } else {
            j -= 1;
        }
    }
    (r_common, a_common)
}

// --------------------------------------------------------------- hunk ranges / line numbers

#[derive(Clone, Copy)]
struct HunkRange {
    old_start: usize,
    old_count: usize,
    new_start: usize,
    new_count: usize,
}

fn parse_range_token(token: &str) -> Option<(usize, usize)> {
    let part = &token[1..];
    let mut it = part.split(',');
    let first = it.next()?;
    if first.is_empty() || !first.bytes().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let start: usize = first.parse().ok()?;
    match it.next() {
        None => Some((start, 1)),
        Some(second) => {
            if it.next().is_some() {
                return None;
            }
            if second.is_empty() || !second.bytes().all(|b| b.is_ascii_digit()) {
                return None;
            }
            let count: usize = second.parse().ok()?;
            Some((start, count))
        }
    }
}

fn parse_hunk_range(raw: &[u8]) -> HunkRange {
    let default = HunkRange {
        old_start: 0,
        old_count: 0,
        new_start: 0,
        new_count: 0,
    };
    let text = String::from_utf8_lossy(raw);
    let tokens: Vec<&str> = text.split_whitespace().collect();
    if tokens.len() < 4 {
        return default;
    }
    let mut idx = 1usize;
    let mut old: Option<(usize, usize)> = None;
    while idx < tokens.len() && tokens[idx].starts_with('-') {
        match parse_range_token(tokens[idx]) {
            Some(r) => old = Some(r),
            None => return default,
        }
        idx += 1;
    }
    let (old_start, old_count) = match old {
        Some(v) => v,
        None => return default,
    };
    if idx >= tokens.len() || !tokens[idx].starts_with('+') {
        return default;
    }
    let (new_start, new_count) = match parse_range_token(tokens[idx]) {
        Some(v) => v,
        None => return default,
    };
    idx += 1;
    if idx >= tokens.len() || !tokens[idx].starts_with('@') {
        return default;
    }
    HunkRange {
        old_start,
        old_count,
        new_start,
        new_count,
    }
}

fn decimal_len(mut n: usize) -> usize {
    if n == 0 {
        return 1;
    }
    let mut len = 0;
    while n > 0 {
        len += 1;
        n /= 10;
    }
    len
}

// --------------------------------------------------------------- output

struct OutputWriter {
    inner: BufWriter<io::Stdout>,
}

impl OutputWriter {
    fn new() -> OutputWriter {
        OutputWriter {
            inner: BufWriter::new(io::stdout()),
        }
    }
    fn write_all(&mut self, bytes: &[u8]) -> AppResult<()> {
        self.inner.write_all(bytes)?;
        Ok(())
    }
    fn flush(&mut self) -> AppResult<()> {
        self.inner.flush()?;
        Ok(())
    }
    fn write_segment(&mut self, face: &Face, text: &[u8]) -> AppResult<()> {
        self.write_all(&face.prefix())?;
        self.write_all(text)?;
        self.write_all(b"\x1b[0m")?;
        Ok(())
    }
    fn write_plain_line(&mut self, line: &RawLine) -> AppResult<()> {
        self.write_segment(&Face::empty(), &line.text)?;
        if line.has_newline {
            self.write_all(b"\n")?;
        }
        Ok(())
    }
}

#[derive(Clone, Copy, PartialEq)]
enum SegmentClass {
    Common,
    Unique,
}

struct LineDisplayInfo {
    indent: Vec<u8>,
    body_start_offset: usize, // offset within content (after prefix)
    no_body: bool,
}

fn analyse_content(content: &[u8]) -> LineDisplayInfo {
    // content is the line text after the +/- prefix character.
    let mut first_non_ws: Option<usize> = None;
    for (i, &b) in content.iter().enumerate() {
        if !is_ascii_ws_byte(b) {
            first_non_ws = Some(i);
            break;
        }
    }
    match first_non_ws {
        None => LineDisplayInfo {
            indent: Vec::new(),
            body_start_offset: content.len(),
            no_body: true,
        },
        Some(idx) => LineDisplayInfo {
            indent: content[..idx].to_vec(),
            body_start_offset: idx,
            no_body: false,
        },
    }
}

// --------------------------------------------------------------- hunk display

struct DisplayState<'a> {
    faces: &'a Faces,
    line_numbers: Option<LineNumberStyle>,
}

fn display_hunk(
    out: &mut OutputWriter,
    hunk: &Hunk,
    opts: &Options,
) -> AppResult<()> {
    // Build token pools.
    let mut removed_tokens: Vec<Token> = Vec::new();
    let mut added_tokens: Vec<Token> = Vec::new();
    // For each line, record token indices: (start_in_pool, end, pool_is_removed?)
    // We keep per-line vectors of token positions plus their classification.
    struct LineTokens {
        removed_idx: Vec<usize>,
        added_idx: Vec<usize>,
        info: Option<LineDisplayInfo>, // for Removed/Added
        content_after_prefix: Vec<u8>,
    }
    let mut per_line: Vec<LineTokens> = Vec::new();
    for (line_idx, line) in hunk.lines.iter().enumerate() {
        let mut lt = LineTokens {
            removed_idx: Vec::new(),
            added_idx: Vec::new(),
            info: None,
            content_after_prefix: Vec::new(),
        };
        if line.kind == LineKind::Removed || line.kind == LineKind::Added {
            let content = if line.raw.text.len() > 0 {
                line.raw.text[1..].to_vec()
            } else {
                Vec::new()
            };
            let info = analyse_content(&content);
            lt.content_after_prefix = content.clone();
            if !info.no_body {
                let body_full = &content[info.body_start_offset..];
                // Trailing CRLF handling: if the line ends with \r\n, the
                // \r is part of the line ending token.
                let (body_for_tokens, crlf) = if line.raw.has_newline
                    && body_full.last() == Some(&b'\r')
                {
                    (&body_full[..body_full.len() - 1], true)
                } else {
                    (body_full, false)
                };
                let toks = tokenize_body(body_for_tokens, line_idx);
                let pool = if line.kind == LineKind::Removed {
                    &mut removed_tokens
                } else {
                    &mut added_tokens
                };
                let idx_vec = if line.kind == LineKind::Removed {
                    &mut lt.removed_idx
                } else {
                    &mut lt.added_idx
                };
                for t in toks {
                    idx_vec.push(pool.len());
                    pool.push(t);
                }
                if line.raw.has_newline {
                    let nl = if crlf {
                        Token {
                            text: b"\r\n".to_vec(),
                            display: b"\r".to_vec(),
                            kind: TokenKind::Newline,
                            line_index: line_idx,
                            is_newline: true,
                        }
                    } else {
                        Token {
                            text: b"\n".to_vec(),
                            display: Vec::new(),
                            kind: TokenKind::Newline,
                            line_index: line_idx,
                            is_newline: true,
                        }
                    };
                    idx_vec.push(pool.len());
                    pool.push(nl);
                }
            } else {
                // No body tokens, but a newline token may still take part.
                if line.raw.has_newline {
                    let pool = if line.kind == LineKind::Removed {
                        &mut removed_tokens
                    } else {
                        &mut added_tokens
                    };
                    let idx_vec = if line.kind == LineKind::Removed {
                        &mut lt.removed_idx
                    } else {
                        &mut lt.added_idx
                    };
                    idx_vec.push(pool.len());
                    pool.push(Token {
                        text: b"\n".to_vec(),
                        display: Vec::new(),
                        kind: TokenKind::Newline,
                        line_index: line_idx,
                        is_newline: true,
                    });
                }
            }
            lt.info = Some(info);
        }
        per_line.push(lt);
    }

    let (removed_common, added_common) = classify_tokens(&removed_tokens, &added_tokens);

    // Line-number preparation.
    let range = parse_hunk_range(&hunk.header.text);
    let (mut old_no, mut new_no) = (range.old_start, range.new_start);
    let end_old = range.old_start.wrapping_add(range.old_count);
    let end_new = range.new_start.wrapping_add(range.new_count);
    let w_compact = std::cmp::max(decimal_len(end_old), decimal_len(end_new));
    let w = match opts.line_numbers {
        Some(LineNumberStyle::Fixed) => std::cmp::max(w_compact, 3),
        _ => w_compact,
    };

    // Header line.
    out.write_plain_line(&hunk.header)?;

    for (line_idx, line) in hunk.lines.iter().enumerate() {
        let lt = &per_line[line_idx];
        match line.kind {
            LineKind::Context => {
                if let Some(style) = opts.line_numbers {
                    let field = if old_no == new_no {
                        format!("{:>width$}", old_no, width = 2 * w + 1)
                    } else {
                        format!("{:>w$} {:>w$}", old_no, new_no, w = w)
                    };
                    out.write_all(field.as_bytes())?;
                    if style == LineNumberStyle::Aligned {
                        out.write_all(b"\t")?;
                    }
                }
                old_no = old_no.wrapping_add(1);
                new_no = new_no.wrapping_add(1);
                out.write_plain_line(&line.raw)?;
            }
            LineKind::Other => {
                out.write_plain_line(&line.raw)?;
            }
            LineKind::Removed | LineKind::Added => {
                let is_removed = line.kind == LineKind::Removed;
                let common_face = if is_removed {
                    opts.faces.removed
                } else {
                    opts.faces.added
                };
                // Line-numbers: check for the formatting failure first.
                if let Some(style) = opts.line_numbers {
                    let (relevant, other, relevant_end) = if is_removed {
                        (old_no, new_no, end_old)
                    } else {
                        (new_no, old_no, end_new)
                    };
                    if relevant_end == 0 {
                        let _ = out.flush();
                        return write_zero();
                    }
                    if decimal_len(relevant) > w {
                        let _ = out.flush();
                        return write_zero();
                    }
                    if relevant == 0 && other != 0 {
                        let _ = out.flush();
                        return write_zero();
                    }
                    if other != 0
                        && ((range.old_start == 0 && old_no != 0)
                            || (range.new_start == 0 && new_no != 0))
                    {
                        let _ = out.flush();
                        return write_zero();
                    }
                    let field = if other == 0 {
                        format!("{:>w$}", relevant, w = w)
                    } else if is_removed {
                        format!("{:>w$} {:>w$}", relevant.to_string(), "", w = w)
                    } else {
                        format!("{:>w$} {:>w$}", "", relevant.to_string(), w = w)
                    };
                    out.write_segment(&common_face, field.as_bytes())?;
                    if style == LineNumberStyle::Aligned {
                        out.write_all(b"\t")?;
                    }
                }
                // Increment counters for this line.
                if is_removed {
                    old_no = old_no.wrapping_add(1);
                } else {
                    new_no = new_no.wrapping_add(1);
                }

                let info = lt.info.as_ref().unwrap();
                // Prefix segment: sign (plus indent when there is a body).
                let mut prefix_text: Vec<u8> = Vec::new();
                prefix_text.push(line.raw.text[0]);
                if !info.no_body {
                    prefix_text.extend_from_slice(&info.indent);
                }
                out.write_segment(&common_face, &prefix_text)?;

                if info.no_body {
                    if !lt.content_after_prefix.is_empty() || line.raw.has_newline {
                        out.write_segment(
                            &Faces::bg_red_only(),
                            &lt.content_after_prefix,
                        )?;
                    }
                    if line.raw.has_newline {
                        out.write_all(b"\n")?;
                    }
                    continue;
                }

                // Token segments.
                let (pool, commons, idxs) = if is_removed {
                    (&removed_tokens, &removed_common, &lt.removed_idx)
                } else {
                    (&added_tokens, &added_common, &lt.added_idx)
                };
                // Build groups of consecutive tokens with equal class.
                struct Group {
                    common: bool,
                    token_positions: Vec<usize>, // positions within idxs
                }
                let mut groups: Vec<Group> = Vec::new();
                for (pos, &ti) in idxs.iter().enumerate() {
                    let is_common = commons[ti];
                    if let Some(last) = groups.last_mut() {
                        if last.common == is_common {
                            last.token_positions.push(pos);
                            continue;
                        }
                    }
                    groups.push(Group {
                        common: is_common,
                        token_positions: vec![pos],
                    });
                }
                for group in &groups {
                    // Concatenate display text.
                    let mut text: Vec<u8> = Vec::new();
                    for &pos in &group.token_positions {
                        text.extend_from_slice(&pool[idxs[pos]].display);
                    }
                    let face = if group.common {
                        common_face
                    } else {
                        // Special trailing-whitespace case.
                        let mut special = false;
                        if group.token_positions.len() == 1 {
                            let ti = idxs[group.token_positions[0]];
                            let tok = &pool[ti];
                            if !tok.is_newline
                                && tok.kind == TokenKind::Whitespace
                                && tok.text.iter().all(|&b| is_ascii_ws_byte(b))
                            {
                                // Last body token?
                                let is_last_body = {
                                    // position of this token within line idxs:
                                    // it must be the last non-newline token.
                                    let mut last_non_nl: Option<usize> = None;
                                    for (p2, &ti2) in idxs.iter().enumerate() {
                                        if !pool[ti2].is_newline {
                                            last_non_nl = Some(p2);
                                        }
                                    }
                                    last_non_nl == Some(group.token_positions[0])
                                };
                                if is_last_body {
                                    // Newline token exists and is common?
                                    if let Some(&last_ti) = idxs.last() {
                                        if pool[last_ti].is_newline && commons[last_ti] {
                                            special = true;
                                        }
                                    }
                                }
                            }
                        }
                        if special {
                            Faces::bg_red_only()
                        } else if is_removed {
                            opts.faces.refine_removed
                        } else {
                            opts.faces.refine_added
                        }
                    };
                    out.write_segment(&face, &text)?;
                }
                if line.raw.has_newline {
                    out.write_all(b"\n")?;
                }
            }
        }
    }
    Ok(())
}

// --------------------------------------------------------------- main processing

fn process<R: Read>(reader: R, out: &mut OutputWriter, opts: &Options) -> AppResult<()> {
    let mut buf_reader = BufReader::new(reader);
    let mut hunk: Option<Hunk> = None;
    loop {
        let mut raw = Vec::new();
        let n = buf_reader.read_until(b'\n', &mut raw)?;
        if n == 0 {
            break;
        }
        let has_newline = raw.last() == Some(&b'\n');
        let text = if has_newline {
            raw[..raw.len() - 1].to_vec()
        } else {
            raw.clone()
        };
        let line = RawLine {
            text: text.clone(),
            has_newline,
        };
        let first = text.first().copied();
        if hunk.is_some() {
            if first == Some(b'@') {
                let taken = hunk.take().unwrap();
                display_hunk(out, &taken, opts)?;
                hunk = Some(Hunk {
                    header: line,
                    lines: Vec::new(),
                });
                continue;
            }
            let kind = match first {
                Some(b' ') => Some(LineKind::Context),
                Some(b'-') => Some(LineKind::Removed),
                Some(b'+') => Some(LineKind::Added),
                Some(b'\\') => Some(LineKind::Other),
                _ => None,
            };
            if let Some(k) = kind {
                hunk.as_mut().unwrap().lines.push(HunkLine { kind: k, raw: line });
                continue;
            } else {
                let taken = hunk.take().unwrap();
                display_hunk(out, &taken, opts)?;
                // fall through: process as an outside line
                out.write_plain_line(&line)?;
            }
        } else {
            if first == Some(b'@') {
                hunk = Some(Hunk {
                    header: line,
                    lines: Vec::new(),
                });
            } else {
                out.write_plain_line(&line)?;
            }
        }
    }
    if let Some(taken) = hunk.take() {
        display_hunk(out, &taken, opts)?;
    }
    out.flush()?;
    Ok(())
}

fn run(opts: Options) -> AppResult<()> {
    let stdin = io::stdin();
    let reader = stdin.lock();
    let mut out = OutputWriter::new();
    let result = process(reader, &mut out, &opts);
    match result {
        Ok(()) => {
            out.flush()?;
            Ok(())
        }
        Err(e) => {
            let _ = out.flush();
            Err(e)
        }
    }
}

fn main() {
    if env::args().any(|arg| arg == "--help") {
        let _ = io::stdout().write_all(LONG_HELP.as_bytes());
        return;
    }
    let args: Vec<String> = env::args().skip(1).collect();
    let mut faces = Faces::defaults();
    let mut line_numbers: Option<LineNumberStyle> = None;
    let mut i = 0usize;
    while i < args.len() {
        let arg = args[i].clone();
        match arg.as_str() {
            "-h" => {
                let _ = io::stdout().write_all(SHORT_HELP.as_bytes());
                return;
            }
            "-V" | "--version" => {
                let _ = io::stderr().write_all(format!("diffr {}\n", VERSION).as_bytes());
                return;
            }
            "--colors" => {
                i += 1;
                if i >= args.len() {
                    let _ = io::stderr().write_all(b"option requires an argument: '--colors'\n");
                    process::exit(2);
                }
                let spec = args[i].clone();
                match apply_color_spec(&mut faces, &spec) {
                    Ok(()) => {}
                    Err(e) => {
                        let _ = io::stderr().write_all(format!("{}\n", e).as_bytes());
                        process::exit(-1);
                    }
                }
            }
            "--line-numbers" => {
                i += 1;
                if i >= args.len() {
                    line_numbers = Some(LineNumberStyle::Compact);
                } else {
                    let value = args[i].clone();
                    match value.as_str() {
                        "compact" => line_numbers = Some(LineNumberStyle::Compact),
                        "aligned" => line_numbers = Some(LineNumberStyle::Aligned),
                        "fixed" => line_numbers = Some(LineNumberStyle::Fixed),
                        _ => {
                            let _ = io::stderr().write_all(
                                format!(
                                    "unexpected line number style: got '{}', expected aligned|compact|fixed\n",
                                    value
                                )
                                .as_bytes(),
                            );
                            process::exit(-1);
                        }
                    }
                }
            }
            _ => {
                let _ = io::stderr().write_all(
                    format!("bad argument: '{}'\n{}", arg, SHORT_HELP).as_bytes(),
                );
                process::exit(2);
            }
        }
        i += 1;
    }

    let opts = Options {
        faces,
        line_numbers,
    };
    match run(opts) {
        Ok(()) => {}
        Err(AppError::Io(e)) => {
            if e.kind() == io::ErrorKind::BrokenPipe {
                process::exit(0);
            }
            let _ = io::stderr().write_all(format!("io error: {}\n", e).as_bytes());
            process::exit(-1);
        }
        Err(AppError::Message(m)) => {
            let _ = io::stderr().write_all(format!("{}\n", m).as_bytes());
            process::exit(-1);
        }
    }
}
