import pathlib
p=pathlib.Path("src/main.rs"); s=p.read_text()
anchor="""    {
        let variant: u32 = std::env::var("TEST_VARIANT")"""
assert anchor in s
insert="""    {
        let variant: u32 = std::env::var("TEST_VARIANT")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(0);
        if variant == 10 {
            // Myers O(ND) algorithm
            let nn = n as i32;
            let mm = m as i32;
            let max_d = nn + mm;
            let offset = max_d;
            let size = (2 * max_d + 1) as usize;
            let mut v = vec![0i32; size];
            let mut trace: Vec<Vec<i32>> = Vec::new();
            let mut found_d: Option<i32> = None;
            for d in 0..=max_d {
                trace.push(v.clone());
                let mut k = -d;
                while k <= d {
                    let idx = (k + offset) as usize;
                    let mut x = if k == -d
                        || (k != d && v[(k - 1 + offset) as usize] < v[(k + 1 + offset) as usize])
                    {
                        v[(k + 1 + offset) as usize]
                    } else {
                        v[(k - 1 + offset) as usize] + 1
                    };
                    let mut y = x - k;
                    while x < nn && y < mm && removed[x as usize].text == added[y as usize].text {
                        x += 1;
                        y += 1;
                    }
                    v[idx] = x;
                    if x >= nn && y >= mm {
                        found_d = Some(d);
                        break;
                    }
                    k += 2;
                }
                if found_d.is_some() {
                    break;
                }
            }
            let found_d = found_d.unwrap_or(max_d);
            let mut x = nn;
            let mut y = mm;
            for d in (0..=found_d).rev() {
                let vd = &trace[d as usize];
                let k = x - y;
                let prev_k = if k == -d
                    || (k != d && vd[(k - 1 + offset) as usize] < vd[(k + 1 + offset) as usize])
                {
                    k + 1
                } else {
                    k - 1
                };
                let prev_x = vd[(prev_k + offset) as usize];
                let prev_y = prev_x - prev_k;
                while x > prev_x && y > prev_y {
                    r_common[(x - 1) as usize] = true;
                    a_common[(y - 1) as usize] = true;
                    x -= 1;
                    y -= 1;
                }
                if d == 0 {
                    break;
                }
                if x == prev_x {
                    // down: insertion in a
                    y -= 1;
                } else {
                    x -= 1;
                }
            }
            return (r_common, a_common);
        }
    }
