{"command":"cat > /tmp/clean_classify.py << 'PY'
import pathlib, re
p=pathlib.Path("src/main.rs"); s=p.read_text()
start=s.index("fn classify_tokens")
end=s.index("// --------------------------------------------------------------- hunk ranges")
new_fn='''fn classify_tokens(removed: &[Token], added: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let n = removed.len();
    let m = added.len();
    let mut r_common = vec![false; n];
    let mut a_common = vec![false; m];
    if n == 0 || m == 0 {
        return (r_common, a_common);
    }
    // Reserve a single trailing newline token as common when both token
    // sequences end with the same newline token.  (Matching the last token
    // is part of some longest common subsequence in any case.)
    let mut r_end = n;
    let mut a_end = m;
    if removed[n - 1].is_newline
        && added[m - 1].is_newline
        && removed[n - 1].text == added[m - 1].text
    {
        r_common[n - 1] = true;
        a_common[m - 1] = true;
        r_end -= 1;
        a_end -= 1;
    }
    // Common prefix: a forward alignment matches equal leading tokens
    // immediately, so trimming them preserves the alignment used below.
    let mut start = 0usize;
    while start < r_end && start < a_end && removed[start].text == added[start].text {
        r_common[start] = true;
        a_common[start] = true;
        start += 1;
    }
    let rn = r_end - start;
    let an = a_end - start;
    if rn == 0 || an == 0 {
        return (r_common, a_common);
    }
    // The quadratic table below is only used for moderate token counts.
    // For very large hunks, leave the remaining tokens unmatched (fully
    // refined), which also keeps the program responsive on huge inputs.
    if (rn as u64) * (an as u64) > 25_000_000 {
        return (r_common, a_common);
    }
    let r_mid = &removed[start..r_end];
    let a_mid = &added[start..a_end];
    // Suffix LCS-length table, used for a forward reconstruction.
    let width = an + 1;
    let mut suf = vec![0u32; (rn + 1) * width];
    for i in (0..rn).rev() {
        for j in (0..an).rev() {
            suf[i * width + j] = if r_mid[i].text == a_mid[j].text {
                suf[(i + 1) * width + (j + 1)] + 1
            } else {
                std::cmp::max(suf[(i + 1) * width + j], suf[i * width + (j + 1)])
            };
        }
    }
    let (mut i, mut j) = (0usize, 0usize);
    while i < rn && j < an {
        if r_mid[i].text == a_mid[j].text {
            r_common[start + i] = true;
            a_common[start + j] = true;
            i += 1;
            j += 1;
        } else if suf[(i + 1) * width + j] > suf[i * width + (j + 1)] {
            i += 1;
        } else {
            j += 1;
        }
    }
    (r_common, a_common)
}

'''
s=s[:start]+new_fn+s[end:]
p.write_text(s)
