end=s.index("// --------------------------------------------------------------- hunk ranges")
new='''fn classify_run_aware(
    removed: &[Token],
    added: &[Token],
    r_common: &mut [bool],
    a_common: &mut [bool],
) {
    let rn = removed.len();
    let an = added.len();
    if rn == 0 || an == 0 {
        return;
    }
    let width = an + 1;
    // A match is worth `big`; continuing an existing run of matches earns
    // one extra point.  Since the maximum possible number of run bonuses
    // is below `big`, this first maximises the number of matched tokens
    // and then prefers alignments that keep matches together in runs.
    let big: i64 = (rn + an + 1) as i64;
    // f(i, j, s): best score aligning removed[i..] with added[j..], where
    // s == 1 means the immediately preceding alignment step was a match.
    let mut f = vec![0i64; (rn + 1) * width * 2];
    let idx = |i: usize, j: usize, s: usize| ((i * width) + j) * 2 + s;
    for i in (0..rn).rev() {
        for j in (0..an).rev() {
            for s in 0..2usize {
                let mut best = std::cmp::max(f[idx(i + 1, j, 0)], f[idx(i, j + 1, 0)]);
                if removed[i].text == added[j].text {
                    let cand = big + (s as i64) + f[idx(i + 1, j + 1, 1)];
                    if cand > best {
                        best = cand;
                    }
                }
                f[idx(i, j, s)] = best;
            }
        }
    }
    let (mut i, mut j, mut st) = (0usize, 0usize, 0usize);
    while i < rn && j < an {
        let cur = f[idx(i, j, st)];
        if removed[i].text == added[j].text && cur == big + (st as i64) + f[idx(i + 1, j + 1, 1)] {
            r_common[i] = true;
            a_common[j] = true;
            i += 1;
            j += 1;
            st = 1;
        } else if f[idx(i + 1, j, 0)] > f[idx(i, j + 1, 0)] {
            i += 1;
            st = 0;
        } else {
            j += 1;
            st = 0;
        }
    }
}

fn classify_tokens(removed: &[Token], added: &[Token]) -> (Vec<bool>, Vec<bool>) {
    let n = removed.len();
    let m = added.len();
    let mut r_common = vec![false; n];
    let mut a_common = vec![false; m];
    if n == 0 || m == 0 {
        return (r_common, a_common);
    }
    if (n as u64) * (m as u64) <= 25_000_000 {
        classify_run_aware(removed, added, &mut r_common, &mut a_common);
        return (r_common, a_common);
    }
    // Large token pools: match a common prefix (and a single trailing
    // newline, when present on both sides), then align what remains if
    // it has become small enough.  Otherwise leave the rest unmatched;
    // this keeps huge inputs fast rather than building a giant table.
    let mut r_end = n;
    let mut a_end = m;
    if removed[n - 1].is_newline
        && added[m - 1].is_newline
        && removed[n - 1].text == added[m - 1].text
    {
        r_common[n - 1] = true;
        a_common[m - 1] = true;
        r_end -= 1;
        a_end -= 1;
    }
    let mut start = 0usize;
    while start < r_end && start < a_end && removed[start].text == added[start].text {
        r_common[start] = true;
        a_common[start] = true;
        start += 1;
    }
    let rn = r_end - start;
    let an = a_end - start;
    if rn > 0 && an > 0 && (rn as u64) * (an as u64) <= 25_000_000 {
        classify_run_aware(
            &removed[start..r_end],
            &added[start..a_end],
            &mut r_common[start..r_end],
            &mut a_common[start..a_end],
        );
    }
    (r_common, a_common)
}

